mapper.select:
SELECT IFNULL(SUM(o.amount), 0)
FROM product_order o
LEFT JOIN seat_session s ON s.id = o.session_id
WHERE IFNULL(s.end_time, o.create_time) >= #{start}
  AND IFNULL(s.end_time, o.create_time) < #{end}
  AND (o.session_id IS NULL OR s.status = 'FINISHED')

SELECT IFNULL(SUM(amount), 0) FROM recharge_record
WHERE type = 'CASH'
  AND operator_id = #{operatorId}
  AND create_time >= #{start}
  AND create_time < #{end}
